
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_jk_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_jk", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.191419581298389e+00, -4.119120641650027e+00, -4.017552970574320e+00, -3.876342166914398e+00, -3.682922958708196e+00, -3.423598365410425e+00, -3.086375504572798e+00, -2.666591729875508e+00, -2.176218506849320e+00, -1.659859922233457e+00, -1.330388052194395e+00, -5.671905646534147e-01, -6.054890139916048e-01, -5.131222369458232e-01, -3.869383072223723e-01, -2.541902606178283e-01, -1.488029829175289e-01, -8.327639158706202e-02, -5.057865731193582e-02, -3.548272456367157e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


